import zipfile
import xml.etree.ElementTree as ET

def local(tag):
    return tag.rsplit('}', 1)[-1]

z = zipfile.ZipFile('budget.xlsx')
root = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))

rows = {}
for el in root.iter():
    if local(el.tag) == 'row':
        r = int(el.attrib.get('r'))
        rows[r] = {}
        for c in el:
            ref = c.attrib.get('r')
            t = c.attrib.get('t', '')
            txt = None
            v = None
            for ch in c:
                ln = local(ch.tag)
                if ln == 'v':
                    v = ch.text
                elif ln == 'is':
                    txt = ''.join(x.text or '' for x in ch.iter() if local(x.tag) == 't')
            if txt is not None:
                rows[r][ref[0]] = txt
            elif v is not None and t == 'n':
                rows[r][ref[0]] = float(v)

items = []
for r in range(11, 23):
    items.append((rows[r]['A'], rows[r]['B'], rows[r]['C']))

total = sum(x[2] for x in items)
print('Line items (Category | Item | Amount):')
for a, b, c in items:
    print(f'  {a} | {b} | {c:g}')
print('SUM(C11:C22) =', total)

cats = {}
for a, b, c in items:
    cats[a] = cats.get(a, 0) + c
print('Per-category subtotals:')
for k, v in cats.items():
    print(f'  {k}: {v:g}')
print('Subtotal check:', sum(cats.values()))
"
